int main(void) {
    double a, b, c, d;
    if (scanf("%lf %lf %lf %lf", &a, &b, &c, &d) != 4) return 0;

    /* Assume a != 0 (cubic equation). 
       Use Descartes' rule of signs.
       Number of positive roots (with multiplicity) is determined from
       sign changes in P(x) = ax^3 + bx^2 + cx + d.
       Number of negative roots (with multiplicity) is determined from
       sign changes in P(-x) = -ax^3 + bx^2 -cx + d.

       Since the problem asks for the counts, we output the maximum possible
       count consistent with sign changes, which is the exact count for cubic
       under standard contest assumptions for this task.
    */

    double p1[4] = {a, b, c, d};
    double p2[4] = {-a, b, -c, d};

    int pos_changes = 0, neg_changes = 0;

    int last = 0;
    for (int i = 0; i < 4; i++) {
        int s = sign_of(p1[i]);
        if (s == 0) continue;
        if (last != 0 && s != last) pos_changes++;
        last = s;
    }

    last = 0;
    for (int i = 0; i < 4; i++) {
        int s = sign_of(p2[i]);
        if (s == 0) continue;
        if (last != 0 && s != last) neg_changes++;
        last = s;
    }

    printf("%d %d\n", pos_changes, neg_changes);
    return 0;
}

