/*
We are given a cubic polynomial
    f(x) = ax^3 + bx^2 + cx + d

We need the number of positive real roots and negative real roots,
counting multiplicities.

Using Vieta:
Let roots be r1, r2, r3 (real or complex), counted with multiplicity.

For a cubic with real coefficients, the number of positive/negative real roots
can be determined by applying Descartes' rule of signs to f(x) and f(-x),
together with the fact that the total number of nonzero real roots counted
with multiplicity is 3 minus the number of nonreal roots, and nonreal roots
come in conjugate pairs.

However, to count multiplicities exactly for a cubic, it is simpler and robust
to compute the real roots numerically from the polynomial and classify them.

Approach:
1. Read coefficients a,b,c,d.
2. Solve the cubic:
   - If it degenerates to quadratic/linear/constant, handle accordingly.
   - Otherwise, reduce to depressed cubic and use Cardano/trigonometric formulas.
3. Collect all real roots with multiplicity.
4. Count how many are > 0 and < 0 with epsilon tolerance.

This directly gives the required counts.
*/

static const long double EPS = 1e-12L;
static const long double PI = acosl(-1.0L);

bool isZero(long double x) {
    return fabsl(x) <= EPS;
}

vector<long double> solveLinear(long double a, long double b) {
    vector<long double> roots;
    if (isZero(a)) return roots;
    roots.push_back(-b / a);
    return roots;
}

vector<long double> solveQuadratic(long double a, long double b, long double c) {
    vector<long double> roots;
    if (isZero(a)) return solveLinear(b, c);

    long double D = b * b - 4.0L * a * c;
    if (D > EPS) {
        long double s = sqrtl(max((long double)0.0, D));
        roots.push_back((-b - s) / (2.0L * a));
        roots.push_back((-b + s) / (2.0L * a));
    } else if (fabsl(D) <= EPS) {
        long double x = -b / (2.0L * a);
        roots.push_back(x);
        roots.push_back(x); // multiplicity 2
    }
    return roots;
}

vector<long double> solveCubic(long double a, long double b, long double c, long double d) {
    vector<long double> roots;

    if (isZero(a)) return solveQuadratic(b, c, d);

    // Normalize: x^3 + A x^2 + B x + C = 0
    long double A = b / a;
    long double B = c / a;
    long double C = d / a;

    // Depressed cubic: y^3 + p y + q = 0, x = y - A/3
    long double shift = A / 3.0L;
    long double p = B - A * A / 3.0L;
    long double q = 2.0L * A * A * A / 27.0L - A * B / 3.0L + C;

    long double D = (q * q) / 4.0L + (p * p * p) / 27.0L;

    if (D > EPS) {
        // One real root
        long double sqrtD = sqrtl(D);
        long double u = cbrtl(-q / 2.0L + sqrtD);
        long double v = cbrtl(-q / 2.0L - sqrtD);
        long double y = u + v;
        roots.push_back(y - shift);
    } else if (fabsl(D) <= EPS) {
        // Multiple roots
        if (isZero(q) && isZero(p)) {
            long double x = -shift;
            roots.push_back(x);
            roots.push_back(x);
            roots.push_back(x);
        } else {
            long double u = cbrtl(-q / 2.0L);
            long double y1 = 2.0L * u;
            long double y2 = -u;
            roots.push_back(y1 - shift);
            roots.push_back(y2 - shift);
            roots.push_back(y2 - shift); // double root
        }
    } else {
        // Three distinct real roots
        long double r = sqrtl(-p / 3.0L);
        long double phi = acosl(max((long double)-1.0, min((long double)1.0, -q / (2.0L * r * r * r))));
        for (int k = 0; k < 3; ++k) {
            long double y = 2.0L * r * cosl((phi + 2.0L * PI * k) / 3.0L);
            roots.push_back(y - shift);
        }
    }

    return roots;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long double a, b, c, d;
    if (!(cin >> a >> b >> c >> d)) return 0;

    vector<long double> roots = solveCubic(a, b, c, d);

    int pos = 0, neg = 0;
    for (long double x : roots) {
        if (x > EPS) pos++;
        else if (x < -EPS) neg++;
        // roots very close to 0 are neither positive nor negative
    }

    cout << pos << " " << neg << "\n";
    return 0;
}

