        if (x1 > x2) swap(x1, x2);
        crits = {-1e18, x1, x2, 1e18};
    }

    // Find roots in each interval using bisection
    vector<double> roots;
    auto bisect = [&](double lo, double hi) {
        double flo = f(lo), fhi = f(hi);
        if (flo * fhi > 0) return;
        for (int i = 0; i < 200; i++) {
            double mid = (lo + hi) / 2;
            if (f(mid) * flo <= 0) hi = mid;
            else { lo = mid; flo = f(mid); }
        }
        roots.push_back((lo + hi) / 2);
    };

    for (int i = 0; i + 1 < (int)crits.size(); i++) {
        bisect(crits[i], crits[i+1]);
    }
    // Check for double roots at critical points
    for (int i = 1; i + 1 < (int)crits.size(); i++) {
        double x = crits[i];
        if (abs(f(x)) < 1e-9) {
            roots.push_back(x);
            roots.push_back(x);
        }
    }

    sort(roots.begin(), roots.end());
    roots.erase(unique(roots.begin(), roots.end()), roots.end());
