# We assume input gives coefficients of a cubic:
# a*x^3 + b*x^2 + c*x + d = 0
# and we need the counts of positive and negative real roots, with multiplicity.
#
# Use Sturm sequence to count roots in intervals:
#   positive roots = roots in (0, +inf)
#   negative roots = roots in (-inf, 0)
#
# For a cubic this is robust and naturally counts multiplicities correctly
# when combined with square-free reduction:
# if gcd(P, P') != 1, repeated roots exist; Sturm should be applied to the
# square-free part, then multiplicities are restored by checking repeated factors.
#
# Since the problem statement is minimal, we implement a reliable exact method
# using integer/rational arithmetic where possible.

from fractions import Fraction

def trim(p):
    while p and p[-1] == 0:
        p.pop()
    return p

def deg(p):
    return len(p) - 1

def lc(p):
    return p[-1] if p else Fraction(0)

def poly_deriv(p):
    return trim([p[i+1] * (i+1) for i in range(len(p)-1)])

def poly_neg(p):
    return [ -x for x in p ]

def poly_divmod(a, b):
    a = a[:]
    trim(a)
    b = b[:]
    trim(b)
    if not b:
        raise ZeroDivisionError
    if deg(a) < deg(b):
        return [Fraction(0)], a
    q = [Fraction(0)] * (deg(a) - deg(b) + 1)
    while a and deg(a) >= deg(b):
        k = deg(a) - deg(b)
        coef = lc(a) / lc(b)
        q[k] = coef
        for i in range(len(b)):
            a[k+i] -= coef * b[i]
        trim(a)
    return trim(q), trim(a)

def poly_gcd(a, b):
    a = trim(a[:])
    b = trim(b[:])
    while b:
        _, r = poly_divmod(a, b)
        a, b = b, r
    if a:
        lead = lc(a)
        a = [x / lead for x in a]
    return a

def poly_eval(p, x):
    res = Fraction(0)
    for coef in reversed(p):
        res = res * x + coef
    return res

def sturm_sequence(p):
    seq = [trim(p[:]), poly_deriv(p)]
    while seq[-1]:
        _, r = poly_divmod(seq[-2], seq[-1])
        r = poly_neg(r)
        trim(r)
        seq.append(r)
    if not seq[-1]:
        seq.pop()
    return seq

def sign_at_infinity(p, pos_inf=True):
    if not p:
        return 0
    s = 1 if lc(p) > 0 else -1
    if not pos_inf and deg(p) % 2 == 1:
        s = -s
    return s

def sign_variations(signs):
    arr = [s for s in signs if s != 0]
    cnt = 0
    for i in range(1, len(arr)):
        if arr[i] != arr[i-1]:
            cnt += 1
    return cnt

def sturm_roots_interval_open(seq, left, right):
    # Count distinct real roots in (left, right)
    # left/right can be 0 or +/-inf represented by None with side info
    def signs_at(x, inf_type=None):
        signs = []
        if inf_type == '+':
            for p in seq:
                signs.append(sign_at_infinity(p, True))
        elif inf_type == '-':
            for p in seq:
                signs.append(sign_at_infinity(p, False))
        else:
            for p in seq:
                v = poly_eval(p, x)
                signs.append(0 if v == 0 else (1 if v > 0 else -1))
        return signs

    if left is None:
        v_left = sign_variations(signs_at(None, '-'))
    else:
        v_left = sign_variations(signs_at(left))
    if right is None:
        v_right = sign_variations(signs_at(None, '+'))
    else:
        v_right = sign_variations(signs_at(right))
    return v_left - v_right

def factor_counts_cubic(a, b, c, d):
    # Polynomial coefficients low->high
    p = [Fraction(d), Fraction(c), Fraction(b), Fraction(a)]
    trim(p)

    # Square-free part
    dp = poly_deriv(p)
    g = poly_gcd(p, dp)
    if deg(g) >= 1:
        q, _ = poly_divmod(p, g)
        sf = q
    else:
        sf = p

    seq = sturm_sequence(sf)

    distinct_pos = sturm_roots_interval_open(seq, Fraction(0), None)
    distinct_neg = sturm_roots_interval_open(seq, None, Fraction(0))

    # Restore multiplicities from repeated factors.
    # For cubic, gcd degree can only be 0,1,2.
    pos = distinct_pos
    neg = distinct_neg

    if deg(g) == 1:
        # one repeated root factor
        # root of g
        r = -g[0] / g[1]
        if r > 0:
            pos += 1
        elif r < 0:
            neg += 1
    elif deg(g) == 2:
        # cubic with triple root: p = (x-r)^3 up to scale
        # g is proportional to (x-r)^2, repeated root contributes +2 beyond square-free one
        # root from derivative gcd double factor
        # For monic quadratic ax^2+bx+c with double root if discriminant 0
        A, B, C = g[2], g[1], g[0]
        r = -B / (2*A)
        if r > 0:
            pos += 2
        elif r < 0:
            neg += 2

    return pos, neg

