        int negativeRoots = countSignChanges(new int[]{a, -b, c, -d});

        // Adjust for zero root
        if (d == 0) {
            // Factor out x: equation becomes x * (ax^2 + bx + c) = 0
            // One root is zero (neither positive nor negative)
            // Count roots of quadratic for positive and negative separately
            int quadPositive = countSignChanges(new int[]{a, b, c});
            int quadNegative = countSignChanges(new int[]{a, -b, c});
            positiveRoots = quadPositive;
            negativeRoots = quadNegative;
        }

        System.out.println(positiveRoots + " " + negativeRoots);
    }

    // Count number of sign changes in the coefficient list (ignoring zeros)
    private static int countSignChanges(int[] coeffs) {
        int changes = 0;
        int lastSign = 0;

        for (int coeff : coeffs) {
            if (coeff > 0) {
                if (lastSign < 0) changes++;
                lastSign = 1;
            } else if (coeff < 0) {
                if (lastSign > 0) changes++;
                lastSign = -1;
            }
        }
        return changes;
    }
}

