public class Main {
    static final double EPS = 1e-10;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        double a = fs.nextDouble();
        double b = fs.nextDouble();
        double c = fs.nextDouble();
        double d = fs.nextDouble();

        // We assume a != 0 since the equation is cubic: a*x^3 + b*x^2 + c*x + d = 0

        int positive = countPositiveRoots(a, b, c, d);
        int negative = countNegativeRoots(a, b, c, d);

        System.out.println(positive + " " + negative);
    }

    // Count positive real roots (with multiplicity) using Sturm sequence on (0, +inf)
    static int countPositiveRoots(double a, double b, double c, double d) {
        double[][] sturm = buildSturm(a, b, c, d);
        int v0 = signVariationsAtZeroPlus(sturm);
        int vinf = signVariationsAtPlusInf(sturm);
        return v0 - vinf;
    }

    // Count negative real roots (with multiplicity) by substituting x = -t and counting positive roots of transformed polynomial
    static int countNegativeRoots(double a, double b, double c, double d) {
        // P(-t) = -a t^3 + b t^2 - c t + d
        double[][] sturm = buildSturm(-a, b, -c, d);
        int v0 = signVariationsAtZeroPlus(sturm);
        int vinf = signVariationsAtPlusInf(sturm);
        return v0 - vinf;
    }

    // Build Sturm sequence for cubic polynomial
    // Polynomial represented as coefficients in descending powers
    static double[][] buildSturm(double a, double b, double c, double d) {
        ArrayList<double[]> seq = new ArrayList<>();
        double[] p0 = normalize(new double[]{a, b, c, d});
        double[] p1 = normalize(derivative(p0));
        seq.add(p0);
        seq.add(p1);

        while (true) {
            double[] prev = seq.get(seq.size() - 2);
            double[] curr = seq.get(seq.size() - 1);
            double[] rem = polyRemainder(prev, curr);
            rem = negate(rem);
            rem = normalize(rem);
            if (isZero(rem)) break;
            seq.add(rem);
            if (rem.length == 1) break;
        }

        return seq.toArray(new double[0][]);
    }

    static double[] derivative(double[] p) {
        int n = p.length - 1;
        if (n == 0) return new double[]{0};
        double[] res = new double[n];
        for (int i = 0; i < n; i++) {
            res[i] = p[i] * (n - i);
        }
        return normalize(res);
    }

    static double[] polyRemainder(double[] A, double[] B) {
        A = normalize(A);
        B = normalize(B);
        if (isZero(B)) throw new RuntimeException("Division by zero polynomial");

        double[] R = Arrays.copyOf(A, A.length);
        int degB = degree(B);

        while (!isZero(R) && degree(R) >= degB) {
            int degR = degree(R);
            double factor = R[0] / B[0];
            int shift = degR - degB;

            double[] sub = new double[B.length + shift];
            for (int i = 0; i < B.length; i++) {
                sub[i] = B[i] * factor;
            }

            R = subtractAligned(R, sub);
            R = normalize(R);
        }

        return normalize(R);
    }

    static double[] subtractAligned(double[] A, double[] B) {
        int n = Math.max(A.length, B.length);
        double[] a = new double[n];
        double[] b = new double[n];

        System.arraycopy(A, 0, a, n - A.length, A.length);
        System.arraycopy(B, 0, b, n - B.length, B.length);

        double[] res = new double[n];
        for (int i = 0; i < n; i++) res[i] = a[i] - b[i];
        return normalize(res);
    }

    static double[] negate(double[] p) {
        double[] r = new double[p.length];
        for (int i = 0; i < p.length; i++) r[i] = -p[i];
        return r;
    }

    static int degree(double[] p) {
        return normalize(p).length - 1;
    }

    static boolean isZero(double[] p) {
        for (double x : p) if (Math.abs(x) > EPS) return false;
        return true;
    }

    static double[] normalize(double[] p) {
        int i = 0;
        while (i < p.length && Math.abs(p[i]) <= EPS) i++;
        if (i == p.length) return new double[]{0};
        return Arrays.copyOfRange(p, i, p.length);
    }

    static int sign(double x) {
        if (x > EPS) return 1;
        if (x < -EPS) return -1;
        return 0;
    }

    static int signAtZeroPlus(double[] p) {
        // At x -> 0+, sign is determined by constant term
        return sign(p[p.length - 1]);
    }

    static int signAtPlusInf(double[] p) {
        // At x -> +inf, sign is determined by leading coefficient
        return sign(p[0]);
    }

    static int signVariationsAtZeroPlus(double[][] sturm) {
        ArrayList<Integer> signs = new ArrayList<>();
        for (double[] p : sturm) {
            int s = signAtZeroPlus(p);
            if (s != 0) signs.add(s);
        }
        return countVariations(signs);
    }

    static int signVariationsAtPlusInf(double[][] sturm) {
        ArrayList<Integer> signs = new ArrayList<>();
        for (double[] p : sturm) {
            int s = signAtPlusInf(p);
            if (s != 0) signs.add(s);
        }
        return countVariations(signs);
    }

    static int countVariations(ArrayList<Integer> signs) {
        int cnt = 0;
        for (int i = 1; i < signs.size(); i++) {
            if (signs.get(i) != signs.get(i - 1)) cnt++;
        }
        return cnt;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }
